import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.CKd2nDfM.js";const m=JSON.parse('{"title":"Sample images","description":"The pictures the component demos are drawn with. Everything under this folder is served from the site root, so a demo refers to one by its path:…","frontmatter":{},"headers":[],"relativePath":"public/samples/README.md","filePath":"public/samples/README.md","lastUpdated":1788608109000}'),s={name:"public/samples/README.md"};function d(i,e,h,n,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sample-images" tabindex="-1">Sample images <a class="header-anchor" href="#sample-images" aria-label="Permalink to &quot;Sample images&quot;">​</a></h1><p>The pictures the component demos are drawn with. Everything under this folder is served from the site root, so a demo refers to one by its path: <code>/samples/people/anya-sol.webp</code>.</p><table tabindex="0"><thead><tr><th>Folder</th><th>Holds</th><th>Size</th></tr></thead><tbody><tr><td><code>people/</code></td><td>Head-and-shoulders portraits, transparent background</td><td>256x256</td></tr><tr><td><code>photos/</code></td><td>Photographs</td><td>1200px on the long edge</td></tr><tr><td><code>illustrations/</code></td><td>Drawn artwork</td><td>1000px on the long edge</td></tr><tr><td><code>marks/</code></td><td>Product marks, for <code>MPAppLogo</code></td><td>128x128</td></tr></tbody></table><p><code>photos/thumbs/</code> and <code>illustrations/thumbs/</code> hold the same pictures at 480px and 400px. Use a thumbnail wherever the box is small, which is nearly everywhere: the full-size file is for <code>MPImage</code>&#39;s <code>previewSrc</code>, the one place a reader asks for the whole picture.</p><h2 id="where-they-came-from" tabindex="-1">Where they came from <a class="header-anchor" href="#where-they-came-from" aria-label="Permalink to &quot;Where they came from&quot;">​</a></h2><p>Every file is a resized WebP of an asset in <a href="https://github.com/jooy2/sample-assets" target="_blank" rel="noreferrer">jooy2/sample-assets</a>, which is MIT licensed and carries the same copyright as this repository. The portraits are of wholly fictional people; the photographs are generated and are not of a real place.</p><h2 id="adding-one" tabindex="-1">Adding one <a class="header-anchor" href="#adding-one" aria-label="Permalink to &quot;Adding one&quot;">​</a></h2><p>Take it from that repository rather than from anywhere else, convert it with <code>cwebp</code>, and keep the source file&#39;s name minus its dimensions. Nothing here needs to be large — a picture in a demo is read at a few hundred pixels, and the docs site is the one place a component library gets to demonstrate that it cares.</p>',8)])])}const f=t(s,[["render",d]]);export{m as __pageData,f as default};
